// Runs only if the Write Reply agent fails; keeps the customer from seeing an error
const sentiment = <jevclassifier.answers.sentiment.choice>;
const confidence = Number(<jevclassifier.answers.sentiment.confidence> ?? 0);
const base = "Thank you for reaching out. A member of our customer service team will be in contact with you shortly.";
if (sentiment === "angry") {
  return "We're very sorry for the frustration you've experienced, and we've marked your request as a priority. " + base;
}
if (sentiment === "irritated" && confidence >= 0.6) {
  return "We're sorry for the frustration, and thank you for your patience. " + base;
}
return base;

const SENTIMENT_LABELS = { calm: "Calm", irritated: "Irritated/Frustrated", angry: "Very Angry" };
const jev = <jevclassifier.answers.category>;
const scope = <jevclassifier.answers.shoe_scope>;
const jevSentiment = <jevclassifier.answers.sentiment>;
// Category comes from the branch Route by Category selected (null when Jev failed)
const selected = String(<routebycategory.selectedOption> ?? "");
const m = selected.match(/(else-if-\d+|else|if)$/);
const branch = m ? m[1] : null;
const BRANCH_CATEGORY = {
  "else-if-2": "Billing",
  "else-if-3": "Technical Support",
  "else-if-4": "Sales",
  "else-if-5": "Product Return",
  "else-if-6": "Shipping"
};
const category =
  BRANCH_CATEGORY[branch] ??
  ((branch === "else-if-0" && jev && jev.choice === "sales") ? "Sales" : "Other");
const fmt = v => (v != null ? Number(v).toFixed(2) : "n/a");
let categoryReason = "";
if (jev && jev.choice) {
  const p = jev.probabilities || {};
  categoryReason = `${jev.choice} (confidence ${fmt(jev.confidence)}; billing ${fmt(p.billing)}, support ${fmt(p.support)}, sales ${fmt(p.sales)}, return ${fmt(p.return)}, shipping ${fmt(p.shipping)}, other ${fmt(p.other)})`;
} else if (<jevclassifier.error>) {
  categoryReason = `Jev failed, defaulted to Other: ${<jevclassifier.error>}`;
}
let sentiment = null;
let sentimentReason = "";
if (jevSentiment && jevSentiment.choice) {
  sentiment = SENTIMENT_LABELS[jevSentiment.choice] ?? null;
  const p = jevSentiment.probabilities || {};
  sentimentReason = `${jevSentiment.choice} (confidence ${fmt(jevSentiment.confidence)}; calm ${fmt(p.calm)}, irritated ${fmt(p.irritated)}, angry ${fmt(p.angry)})`;
}
let shoeScopeReason = "";
if (scope && scope.choice) {
  const p = scope.probabilities || {};
  shoeScopeReason = `${scope.choice} (confidence ${fmt(scope.confidence)}; unrelated ${fmt(p.unrelated)}, unclear ${fmt(p.unclear)}, clear ${fmt(p.clear)})`;
}
return {
  message: <start.input> ?? "",
  category,
  category_reason: categoryReason,
  conversation_id: <start.conversationId> ?? "",
  source: "Jev",
  sentiment_reason: sentimentReason,
  sentiment,
  shoe_scope_reason: shoeScopeReason,
  createdAt: new Date().toISOString().slice(0, 19)
};
